//! Oracle tests for the typed scene stroke kernel (L07-B / F16).
//!
//! `fixtures/object-scene-style-stroke/oracle.txt` was generated by
//! `tools/gen_oracle.js` from baseline fbe4b8a3. `S` rows run the verbatim stroke
//! block of `buildSceneJson` (engine-bridge.js) and `cssColorToRgba` in a Node
//! `vm` and keep the JSON wire item the engine reads; their last column is a JS
//! transcription of engine.rs `stroke_from`. `P` rows pair a transcription of
//! `dash_pattern_with_offset` with an independent kurbo 0.13.1 on/off model.
//! Rows (space separated, `#` lines are provenance):
//! `S color width pt scale cap join miter dash doff wirehex outcome`,
//! `P e|o pattern offset baked verdict`. Tokens: `U` undefined, `N` null, `~`
//! undefined colour, `=` empty string, `#` non-string, `-` empty list, hex f64
//! bits (comma separated for lists) or UTF-8 hex for text.

use super::{
    EngineStrokeItem, PaintedStroke, SceneCap, SceneJoin, StrokeError, StrokeRules, StrokeSource,
    BASELINE,
};

pub(crate) const ORACLE: &str = include_str!("fixtures/object-scene-style-stroke/oracle.txt");

fn unhex(h: &str) -> Vec<u8> {
    (0..h.len() / 2)
        .map(|i| u8::from_str_radix(&h[2 * i..2 * i + 2], 16).expect("hex byte"))
        .collect()
}

fn bits(tok: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(tok, 16).expect("f64 bits"))
}

fn num(tok: &str) -> Option<f64> {
    (tok != "U" && tok != "N").then(|| bits(tok))
}

fn text(tok: &str) -> Option<String> {
    match tok {
        "U" | "N" | "#" => None,
        "=" => Some(String::new()),
        h => Some(String::from_utf8(unhex(h)).expect("utf8")),
    }
}

fn list(tok: &str) -> Vec<f64> {
    if tok == "-" {
        Vec::new()
    } else {
        tok.split(',').map(bits).collect()
    }
}

fn bits_eq(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits()
}

fn lists_eq(a: &[f64], b: &[f64]) -> bool {
    a.len() == b.len() && a.iter().zip(b).all(|(x, y)| bits_eq(*x, *y))
}

fn rows<'a>(oracle: &'a str, tag: &'a str) -> impl Iterator<Item = Vec<&'a str>> {
    oracle
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|l| l.split(' ').collect::<Vec<&str>>())
        .filter(move |t| t[0] == tag)
}

fn source_of(t: &[&str], wire: &serde_json::Value) -> StrokeSource {
    let color = wire.get("strokeColor").map(|c| {
        let v = c.as_array().expect("colour array");
        [0usize, 1, 2, 3].map(|i| v[i].as_u64().expect("channel") as u8)
    });
    let dash_array = match t[8] {
        "U" | "N" => None,
        other => Some(list(other)),
    };
    StrokeSource {
        color,
        width: num(t[2]),
        path_transform: t[3] == "1",
        stroke_scale: bits(t[4]),
        cap: text(t[5]),
        join: text(t[6]),
        miter_limit: num(t[7]),
        dash_array,
        dash_offset: num(t[9]),
    }
}

fn cap_name(cap: SceneCap) -> &'static str {
    match cap {
        SceneCap::Butt => "Butt",
        SceneCap::Round => "Round",
        SceneCap::Square => "Square",
    }
}

fn join_name(join: SceneJoin) -> &'static str {
    match join {
        SceneJoin::Bevel => "Bevel",
        SceneJoin::Miter => "Miter",
        SceneJoin::Round => "Round",
    }
}

fn check_outcome(
    got: &Result<Option<PaintedStroke>, StrokeError>,
    expected: &[&str],
) -> Option<String> {
    let bad = |why: &str| Some(format!("{why}: got {got:?} want {expected:?}"));
    match (expected[0], got) {
        ("ABSENT", Ok(None)) => None,
        ("ERR:W", Err(StrokeError::NonFiniteWidth)) => None,
        ("ERR:D", Err(StrokeError::NonFiniteDashEntry)) => None,
        ("ERR:P", Err(StrokeError::NonFiniteDashPeriod)) => None,
        ("OK", Ok(Some(painted))) => {
            let s = &painted.stroke;
            let miter_ok = match (num(expected[4]), s.miter_limit) {
                (None, None) => true,
                (Some(a), Some(b)) => bits_eq(a, b),
                _ => false,
            };
            let dash_ok = match (expected[5], &s.dash) {
                ("-", None) => true,
                (tok, Some(d)) => tok != "-" && lists_eq(&list(tok), d),
                _ => false,
            };
            if !bits_eq(bits(expected[1]), s.width) {
                bad("width")
            } else if cap_name(s.cap) != expected[2] || join_name(s.join) != expected[3] {
                bad("cap/join")
            } else if !miter_ok {
                bad("miter")
            } else if !dash_ok {
                bad("dash")
            } else if s.dash_offset() != 0.0 {
                bad("dash offset")
            } else {
                None
            }
        }
        _ => bad("outcome"),
    }
}

/// The verbatim JS wire item must agree with what the kernel treats as input
/// and output, so a drifted transcription column cannot hide a bridge change.
fn check_wire(
    rules: &StrokeRules,
    t: &[&str],
    source: &StrokeSource,
    wire: &serde_json::Value,
) -> Option<String> {
    let absent = t[11] == "ABSENT";
    if wire.get("strokeColor").is_some() == absent {
        return Some("strokeColor presence".to_string());
    }
    if absent {
        let keys = wire.as_object().expect("object");
        return keys
            .keys()
            .any(|k| k != "pathTransform")
            .then(|| "stroke fields without a colour".to_string());
    }
    let dash_len = source.dash_array.as_ref().map_or(0, Vec::len);
    if wire.get("dashPattern").is_some() != (dash_len > 0)
        || wire.get("dashOffset").is_some() != (dash_len > 0 && t[9] != "U")
        || wire.get("miterLimit").is_some() != (t[7] != "U")
    {
        return Some("dash/miter emission".to_string());
    }
    let wire_str = |k: &str| wire.get(k).and_then(|v| v.as_str()).map(str::to_string);
    if wire_str("strokeCap") != source.cap || wire_str("strokeJoin") != source.join {
        return Some("cap/join emission".to_string());
    }
    let width = wire.get("strokeWidth").expect("width present");
    let want = rules.scene_width(source.width, source.path_transform, source.stroke_scale);
    if want.is_finite() {
        (width.as_f64() != Some(want)).then(|| format!("wire width {width:?} vs {want}"))
    } else {
        (!width.is_null()).then(|| format!("non-finite width must be null on the wire: {width:?}"))
    }
}

pub(crate) fn s_mismatches(rules: &StrokeRules, oracle: &str) -> Vec<String> {
    let mut out = Vec::new();
    for t in rows(oracle, "S") {
        let wire: serde_json::Value =
            serde_json::from_str(&String::from_utf8(unhex(t[10])).expect("utf8")).expect("json");
        let source = source_of(&t, &wire);
        let got = rules.scene_stroke(&source);
        let mut why = check_outcome(&got, &t[11..]);
        if why.is_none() {
            why = check_wire(rules, &t, &source, &wire);
        }
        if let Some(why) = why {
            out.push(format!("S {} {} {}: {why}", t[1], t[2], t[3]));
        }
    }
    out
}

/// kurbo 0.13.1 `dash_iter`: odd arrays are doubled, segments alternate on/off.
pub(crate) fn is_on(pattern: &[f64], offset: f64, x: f64) -> bool {
    let mut effective = pattern.to_vec();
    if pattern.len() % 2 == 1 {
        effective.extend_from_slice(pattern);
    }
    let period = effective.iter().fold(0.0, |sum, e| sum + e);
    let t = (x + offset).rem_euclid(period);
    let mut end = 0.0;
    for (index, length) in effective.iter().enumerate() {
        end += length;
        if t < end {
            return index % 2 == 0;
        }
    }
    false
}

/// First probe `j` (x = 0.25 j + 0.125) where baked and original disagree.
pub(crate) fn first_divergence(pattern: &[f64], offset: f64, baked: &[f64]) -> Option<usize> {
    let total = pattern.iter().fold(0.0, |sum, e| sum + e);
    let span = (24.0 * total).ceil() as usize;
    (0..span).find(|j| {
        let x = 0.25 * (*j as f64) + 0.125;
        is_on(pattern, offset, x) != is_on(baked, 0.0, x)
    })
}

pub(crate) fn p_mismatches(rules: &StrokeRules, oracle: &str) -> Vec<String> {
    let mut out = Vec::new();
    for t in rows(oracle, "P") {
        let (pattern, offset, want) = (list(t[2]), bits(t[3]), list(t[4]));
        let got = rules.bake_dash_offset(&pattern, offset).expect("valid");
        let mut why = (!lists_eq(&got, &want)).then(|| format!("baked {got:?} want {want:?}"));
        if why.is_none() && pattern.iter().sum::<f64>() > 0.0 {
            let verdict =
                first_divergence(&pattern, offset, &got).map_or("-".to_string(), |j| j.to_string());
            if verdict != t[5] {
                why = Some(format!("divergence {verdict} want {}", t[5]));
            }
        }
        if let Some(why) = why {
            out.push(format!("P {} {} @{}: {why}", t[1], t[2], t[3]));
        }
    }
    out
}

#[test]
fn oracle_row_counts_are_pinned() {
    assert_eq!(rows(ORACLE, "S").count(), 666);
    assert_eq!(rows(ORACLE, "P").count(), 1300);
    assert_eq!(rows(ORACLE, "P").filter(|t| t[1] == "e").count(), 1000);
    assert_eq!(rows(ORACLE, "P").filter(|t| t[1] == "o").count(), 300);
    let outcome = |name: &str| rows(ORACLE, "S").filter(|t| t[11] == name).count();
    assert_eq!(outcome("ABSENT"), 12);
    assert_eq!(outcome("OK"), 573);
    assert_eq!(outcome("ERR:W"), 36);
    assert_eq!(outcome("ERR:D"), 30);
    assert_eq!(outcome("ERR:P"), 15);
}

#[test]
fn scene_rows_match_the_verbatim_bridge_and_the_engine_transcription() {
    let bad = s_mismatches(&BASELINE, ORACLE);
    assert!(
        bad.is_empty(),
        "{} mismatches, first: {:?}",
        bad.len(),
        bad.first()
    );
}

#[test]
fn baked_patterns_match_the_dash_pattern_with_offset_transcription_bit_for_bit() {
    let bad = p_mismatches(&BASELINE, ORACLE);
    assert!(
        bad.is_empty(),
        "{} mismatches, first: {:?}",
        bad.len(),
        bad.first()
    );
}

#[test]
fn even_arrays_agree_with_the_original_through_the_first_baked_cycle() {
    let mut checked = 0;
    for t in rows(ORACLE, "P").filter(|t| t[1] == "e") {
        let (pattern, offset) = (list(t[2]), bits(t[3]));
        let total: f64 = pattern.iter().sum();
        if total <= 0.0 {
            continue;
        }
        let baked = BASELINE.bake_dash_offset(&pattern, offset).expect("valid");
        let cycle: f64 = baked.iter().sum();
        let span = (24.0 * total).ceil() as usize;
        for j in 0..span {
            let x = 0.25 * (j as f64) + 0.125;
            if x >= cycle {
                break;
            }
            assert_eq!(
                is_on(&baked, 0.0, x),
                is_on(&pattern, offset, x),
                "{pattern:?} @{offset} x={x}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 950, "even rows with a positive total");
}

#[test]
fn the_baseline_bake_drifts_after_the_first_cycle_unless_it_is_a_pure_rotation() {
    let mut diverging = [0usize; 2];
    let (mut exact, mut zero_entry) = (0usize, 0usize);
    for t in rows(ORACLE, "P") {
        let slot = usize::from(t[1] == "o");
        if t[5] != "-" && t[5] != "n/a" {
            diverging[slot] += 1;
        } else if t[5] == "-" && slot == 0 {
            let (pattern, baked) = (list(t[2]), list(t[4]));
            let total: f64 = pattern.iter().sum();
            let cycle: f64 = baked.iter().sum();
            if bits_eq(cycle, total) {
                exact += 1;
            } else {
                // A shorter period is invisible only when a zero-length entry
                // makes the dropped remainder indistinguishable.
                assert!(pattern.contains(&0.0), "{pattern:?} @{}", t[3]);
                zero_entry += 1;
            }
        }
    }
    assert_eq!(
        diverging,
        [696, 255],
        "even / odd rows whose baked array drifts"
    );
    assert_eq!((exact, zero_entry), (198, 56), "even rows without drift");
}

#[test]
fn engine_item_defaults_follow_stroke_from() {
    let item = EngineStrokeItem {
        width: None,
        cap: None,
        join: None,
        miter_limit: None,
        dash_pattern: None,
        dash_offset: None,
    };
    let stroke = BASELINE.engine_stroke(&item).expect("defaults");
    assert_eq!(stroke.width, 1.0);
    assert_eq!(
        (stroke.cap, stroke.join),
        (SceneCap::Round, SceneJoin::Round)
    );
    assert_eq!((stroke.miter_limit, stroke.dash.clone()), (None, None));
    assert_eq!(stroke.effective_miter_limit(), 4.0);
}
